interface Problem {
  readonly locale: string;
  readonly id: string;
  readonly kind: "catalog" | "missing" | "invalid" | "unknown";
  readonly reason: string;
}

async function exists(filePath: string): Promise<boolean> {
  try {
    await access(filePath);
    return true;
  } catch {
    return false;
  }
}

